describe('Table Row Filtering', () => {
    beforeEach(() => {
        cy.visit('/table-page'); // Adjust the URL to your application's table page
    });

    it('should filter table rows based on user input', () => {
        cy.get('input[name="search"]').type('Test Item'); // Replace with the actual input selector
        cy.get('table tbody tr').should('have.length', 1); // Expecting 1 row to match the search
        cy.get('table tbody tr').first().should('contain', 'Test Item'); // Replace with the expected item
    });

    it('should show all rows when search input is cleared', () => {
        cy.get('input[name="search"]').type('Test Item'); // Filter to a specific item
        cy.get('table tbody tr').should('have.length', 1); // Ensure only 1 row is shown
        cy.get('input[name="search"]').clear(); // Clear the search input
        cy.get('table tbody tr').should('have.length.greaterThan', 1); // Expecting more than 1 row to be visible
    });
});
